using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Foundation;

internal sealed class RealRogFailureQuantitativeDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "A supplied normalized rank-one cross pair gives an actual cone gap against every proper confirmer on the entire PSD section.",
        H("Quantitative cross-pair predecessor"),
        Blocks(
            Paragraph(Text("This is the quantitative predecessor in Quantum Origin VI Proposition 93.3, equations (93.22) and (93.24). Its premises explicitly supply trace normalization and a cross pair separated by an effect on the section. The original arbitrary strictly positive unit, full-support compression, determinant maximizer, primal and dual attainment, extraction from a failed local antipodal pair, purity transport and the return to the original carrier remain unpaid. This result does not complete Proposition 93.3 and supplies no block classification, Jordan structure, self-duality or zero-gluing premise.")),
            Describe.Lean(DescribeId.Create("midpoint-psd-gap"),
                DeclarationHandle.Create("D5/S3/Quantum/Foundation/RealRogFailureQuantitative.midpoint_psd_gap"),
                H("The dimension-uniform quadratic estimate"), StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Let the finite coordinate type have cardinality n at least two, and let v and w be arbitrary real vectors with v dot v = w dot w = 1. Write s = v v-transpose, x = w w-transpose, c = (v dot w)^2 and y = (I-s)/(n-1). Then (x+y)/2 - c s/(2n) is positive semidefinite. Orthogonal, equal, opposite and nonorthogonal directions are all allowed in this estimate; strict positivity of c is not a premise.")),
                    Paragraph(Text("The proof constructs the orthogonal residuals b = w-(v dot w)v and h = z-(v dot z)v for each test vector z. Their squared norms and cross product reduce to the original dot products. The finite Cauchy-Schwarz theorem bounds (b dot h)^2 by the squared norm of h. A weighted square then gives c(v dot z)^2 <= n((w dot z)^2 + (z dot z-(v dot z)^2)/(n-1)). The PSD criterion converts this estimate into the actual matrix difference. The normalized section theorem below consumes this cone difference on its live proof path."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("normalized-cross-pair-gap"),
                DeclarationHandle.Create("D5/S3/Quantum/Foundation/RealRogFailureQuantitative.normalized_cross_pair_gap"),
                H("Two zeros and a uniform positive midpoint on the whole section"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Let L be any real linear subspace of the n by n real matrices, n >= 2. The actual carrier is L itself. A pointed cone C on L has membership exactly equivalent to ambient positive semidefiniteness, and the actual linear unit u equals trace at every element of L. Supply j,s,x in L with j = I, s = v v-transpose and x = w w-transpose, where v and w are unit vectors. Assume c = (v dot w)^2 > 0 and supply an arbitrary real linear f on L that is proper on every point of C, confirms s and has f(x)=0. There is no premise that other effects have ambient positive-contraction extensions.")),
                    Paragraph(Text("Set y = (j-s)/(n-1), m = (x+y)/2 and delta = c/(2n). The theorem concludes c < 1; s,x,y,m all lie in the entire normalized base of C and u; T_s(x)=T_s(y)=0; the actual matrix m is positive definite; m-delta s belongs to C; every real linear proper confirmer g of s on L satisfies delta <= g(m); and delta <= T_s(m) with delta > 0. Here T is exactly CircuitBalancedConfirmation.comparison, the infimum over all proper confirming effects on L. The first zero uses the supplied f; the second uses the constructed projection functional A maps to v dot A v. These effects need not coincide.")),
                    Paragraph(Text("The cone difference is obtained from midpoint_psd_gap and stays inside L by its linear operations. Whole-cone positivity of every confirmer gives the common lower bound before taking the infimum. The same quadratic estimate, together with the positive overlap, proves positive definiteness. Unit normalization and the projection effect prove membership and the two zeros directly. Equality c=1 would make x=s and contradict f(x)=0 and f(s)=1. The case n=2 is included, as are arbitrary larger dimensions and their complement states; no rank or extremality conclusion about y is asserted here. There is no finite pure-carrier assumption. The theorem does not prove that such normalized data arise from the original failed antipodal pair."))), DescribeRole.Theorem),
            Paragraph(Text("Reuse: finite Cauchy-Schwarz and the real matrix PSD quadratic criterion are pinned Mathlib inputs. Trace positivity for products of PSD matrices is reused directly from RHLinalg.trace_mul_nonneg_of_posSemidef. The existing base, proper, confirms and comparison definitions are imported from CircuitBalancedConfirmation. No existing private theorem supplies the full normalized mixed-state statement. The new estimate and its actual whole-effect consumer are repository-derived; no literature-priority claim is made.")))));
}
